test('order', () => {
  handle('POST', '/api/kitchens', { name: 'Maa ki Rasoi', rating: 4, opened_on: '2025-01-02' });
  handle('POST', '/api/menus', { kitchen_id: 1, dish: 'Rajma chawal', price: '80', served_on: '2026-11-13' });
  const r = handle('POST', '/api/orders', { menu_id: 1, plates: 2, total: '160', placed_on: '2026-11-14' });
